-- Evaluate request bodies as APISIX request-validation does: schemas loaded from
-- YAML by lyaml (standalone config_provider), bodies decoded by
-- apisix.core.json, validators generated by jsonschema with the options of
-- apisix.core.schema (skip_validation = apisix.secret.is_secret_ref, inlined
-- because loading apisix.core needs a full APISIX prefix).
-- Usage: resty apisix_schema_parity.lua <schemas.yaml> <cases.json>
package.cpath = "/usr/local/apisix/deps/lib/lua/5.1/?.so;" .. package.cpath
local lyaml = require("lyaml")
local cjson = require("cjson.safe")
local core_json = require("apisix.core.json")
local jsonschema = require("jsonschema")

local function is_secret_ref(value, schema)
  if type(value) ~= "string" or string.byte(value, 1) ~= 36 then return false end
  if schema and schema.type and schema.type ~= "string" then return false end
  return value:sub(1, 10) == "$secret://" or value:upper():sub(1, 7) == "$ENV://"
end

local schemas = lyaml.load(assert(io.open(arg[1])):read("*a"))
local cases = assert(cjson.decode(assert(io.open(arg[2])):read("*a")))
local validators = {}
for i, case in ipairs(cases) do
  local uri = case[1]
  if not validators[uri] then
    validators[uri] = assert(jsonschema.generate_validator(assert(schemas[uri], "missing " .. uri),
      {skip_validation = is_secret_ref}))
  end
  local body = assert(core_json.decode(case[2]))
  local ok, err = validators[uri](body)
  io.write(i, "\t", ok and "1" or "0", "\t", ok and "" or (string.gsub(tostring(err), "[\r\n\t]", " ")), "\n")
end
io.write("DONE\t", #cases, "\n")
